1	// Package incidents holds the incident-handling register: incidents are
2	// created once, evolve through append-only actions under optimistic
3	// concurrency, and link back to events without modifying them.
4	package incidents
5	
6	import (
7		"errors"
8		"fmt"
9		"slices"
10		"strings"
11		"sync"
12		"time"
13	)
14	
15	// Incident statuses.
16	const (
17		StatusOpen     = "open"
18		StatusResolved = "resolved"
19	)
20	
21	// Actions accepted by POST /incidents/{id}/actions. ActionCreate marks the
22	// creation entry in an incident's history.
23	const (
24		ActionCreate            = "create"
25		ActionNote              = "add_note"
26		ActionLinkEvent         = "link_event"
27		ActionResolve           = "resolve"
28		ActionReopen            = "reopen"
29		ActionAddParticipant    = "add_participant"
30		ActionRemoveParticipant = "remove_participant"
31		ActionAssignOwner       = "assign_owner"
32	)
33	
34	// ValidationError reports missing fields, wrong types, or unknown actions.
35	type ValidationError struct{ Reason string }
36	
37	func (e *ValidationError) Error() string { return e.Reason }
38	
39	// NotFoundError reports a missing incident or a missing linked event.
40	type NotFoundError struct{ Reason string }
41	
42	func (e *NotFoundError) Error() string { return e.Reason }
43	
44	// ConflictError carries the current incident version alongside the reason,
45	// so a stale-version response can report it. CurrentVersion is zero when the
46	// conflict is not version-related.
47	type ConflictError struct {
48		Reason         string
49		CurrentVersion int
50	}
51	
52	func (e *ConflictError) Error() string { return e.Reason }
53	
54	// IsValidationError reports whether err is an incident validation failure.
55	func IsValidationError(err error) bool {
56		var target *ValidationError
57		return errors.As(err, &target)
58	}
59	
60	// IsNotFoundError reports whether err is a missing-incident/event failure.
61	func IsNotFoundError(err error) bool {
62		var target *NotFoundError
63		return errors.As(err, &target)
64	}
65	
66	// IsConflictError reports whether err is an incident conflict failure.
67	func IsConflictError(err error) bool {
68		var target *ConflictError
69		return errors.As(err, &target)
70	}
71	
72	// MaxActionPayloadBytes bounds the saved JSON of one newly saved action
73	// record: the MarshalRecord output, including the record's own fields and
74	// its server timestamp, but excluding the 8-byte storage frame header. It is
75	// 64 MiB in 1024*1024-byte units, matching the durable frame capacity. A
76	// record encoding to exactly this size is still accepted; only a larger
77	// encoding is rejected.
78	const MaxActionPayloadBytes = 64 << 20
79	
80	// OversizeActionError reports that a legal new note's normalized action
81	// record encodes to more than MaxActionPayloadBytes in the save format. It
82	// is a property of the submitted content, not of storage: the save format
83	// JSON-escapes characters such as '&', '<', and '>', so a request well under
84	// the 16 MiB body limit can still save far larger. Nothing is written or
85	// committed when it is returned, so the incident keeps its prior version,
86	// history, people, and links, the rejected action id stays free for a
87	// shortened retry, and incident storage remains usable without a restart.
88	type OversizeActionError struct {
89		Size  int
90		Limit int
91	}
92	
93	func (e *OversizeActionError) Error() string {
94		return fmt.Sprintf("incident note saves to %d bytes, exceeding the %d byte (64 MiB) save capacity of a single incident record; reduce the amount of content in this submission", e.Size, e.Limit)
95	}
96	
97	// IsOversizeActionError reports whether err is a note whose saved record
98	// exceeds the per-record save capacity, as opposed to a validation,
99	// conflict, or storage failure.
100	func IsOversizeActionError(err error) bool {
101		var target *OversizeActionError
102		return errors.As(err, &target)
103	}
104	
105	// CurrentVersionOf returns the version reported with a version conflict, or
106	// zero when err is not a version conflict.
107	func CurrentVersionOf(err error) int {
108		var target *ConflictError
109		if errors.As(err, &target) {
110			return target.CurrentVersion
111		}
112		return 0
113	}
114	
115	func validationErr(format string, args ...any) error {
116		return &ValidationError{Reason: fmt.Sprintf(format, args...)}
117	}
118	
119	func notFoundErr(format string, args ...any) error {
120		return &NotFoundError{Reason: fmt.Sprintf(format, args...)}
121	}
122	
123	func conflictErr(currentVersion int, format string, args ...any) error {
124		return &ConflictError{Reason: fmt.Sprintf(format, args...), CurrentVersion: currentVersion}
125	}
126	
127	// Creation is the normalized content of POST /incidents. Strings are trimmed
128	// of surrounding whitespace but keep their interior case.
129	type Creation struct {
130		ID       string
131		Title    string
132		Service  string
133		Operator string
134	}
135	
136	// Request is the normalized content of POST /incidents/{id}/actions. Content
137	// carries the action payload: the note text, the linked event id, or the
138	// resolve/reopen reason.
139	type Request struct {
140		IncidentID      string
141		ActionID        string
142		Operator        string
143		ExpectedVersion int
144		Type            string
145		Content         string
146	}
147	
148	// CreateResult is the result of a successful create, including an idempotent
149	// replay.
150	type CreateResult struct {
151		ID      string
152		Status  string
153		Version int
154	}
155	
156	// ActionResult is the result of a successful action, including an idempotent
157	// replay.
158	type ActionResult struct {
159		IncidentID string
160		ActionID   string
161		Version    int
162	}
163	
164	// Entry is one committed item in an incident's history: the creation itself
165	// or a later action.
166	type Entry struct {
167		ActionID string
168		Operator string
169		Action   string
170		Content  string
171		Version  int
172		At       time.Time
173	}
174	
175	// Incident is one committed snapshot, suitable for a single-version read.
176	type Incident struct {
177		ID           string
178		Title        string
179		Service      string
180		Status       string
181		Version      int
182		Participants []string
183		Owner        string
184		Links        []string
185		History      []Entry
186	}
187	
188	// EventLookup resolves an event id without exposing the whole timeline, so
189	// incident handling never modifies events.
190	type EventLookup interface {
191		// LookupEvent returns (service, true) for a stored event, or ("", false).
192		LookupEvent(id string) (service string, ok bool)
193	}
194	
195	// BeforeCommit persists one new record while the registry lock is held and
196	// before the in-memory state advances. Returning an error rejects the request
197	// without touching the incident.
198	type BeforeCommit func(record Record) error
199	
200	// Registry is the concurrency-safe set of incidents.
201	type Registry struct {
202		mu        sync.Mutex
203		incidents map[string]*incidentState
204	
205		events       EventLookup
206		beforeCommit BeforeCommit
207		now          func() time.Time
208	}
209	
210	// incidentState is the mutable state of one incident.
211	type incidentState struct {
212		id      string
213		title   string
214		service string
215		status  string
216		version int
217	
218		// participants holds every participant name in membership order; the
219		// membership is tracked separately by participantSet. The owner is always
220		// among the participants. A newly created incident starts with only its
221		// operator as both participant and owner; note/link operators never join
222		// automatically.
223		participants   []string
224		participantSet map[string]struct{}
225		owner          string
226	
227		links   []string
228		linkSet map[string]struct{}
229	
230		history []Entry
231		// actions remembers each successful action's normalized request and the
232		// version reached afterwards, so an identical retry replays the first
233		// result even once the version has moved on.
234		actions map[string]committedAction
235	
236		creation Creation
237	}
238	
239	type committedAction struct {
240		request       Request
241		resultVersion int
242	}
243	
244	// Option configures a Registry at construction.
245	type Option func(*Registry)
246	
247	// WithClock overrides the server clock, mainly for tests.
248	func WithClock(now func() time.Time) Option {
249		return func(r *Registry) {
250			if now != nil {
251				r.now = now
252			}
253		}
254	}
255	
256	// NewRegistry returns an empty registry. events resolves linked event ids and
257	// beforeCommit durably stores each accepted record.
258	func NewRegistry(events EventLookup, beforeCommit BeforeCommit, opts ...Option) *Registry {
259		r := &Registry{
260			incidents:    make(map[string]*incidentState),
261			events:       events,
262			beforeCommit: beforeCommit,
263			now:          func() time.Time { return time.Now().UTC() },
264		}
265		for _, opt := range opts {
266			opt(r)
267		}
268		return r
269	}
270	
271	// NormalizeCreation trims the four creation fields, keeping their interior
272	// case, and requires each to be non-empty afterwards.
273	func NormalizeCreation(input Creation) (Creation, error) {
274		var err error
275		if input.ID, err = trimRequired("id", input.ID); err != nil {
276			return Creation{}, err
277		}
278		if input.Title, err = trimRequired("title", input.Title); err != nil {
279			return Creation{}, err
280		}
281		if input.Service, err = trimRequired("service", input.Service); err != nil {
282			return Creation{}, err
283		}
284		if input.Operator, err = trimRequired("operator", input.Operator); err != nil {
285			return Creation{}, err
286		}
287		return input, nil
288	}
289	
290	// NormalizeRequest trims and validates one action request. incidentID comes
291	// from the URL path and is only checked for emptiness.
292	func NormalizeRequest(input Request) (Request, error) {
293		var err error
294		if input.IncidentID, err = trimRequired("incident id", input.IncidentID); err != nil {
295			return Request{}, err
296		}
297		if input.ActionID, err = trimRequired("action_id", input.ActionID); err != nil {
298			return Request{}, err
299		}
300		if input.Operator, err = trimRequired("operator", input.Operator); err != nil {
301			return Request{}, err
302		}
303		if input.ExpectedVersion <= 0 {
304			return Request{}, validationErr("expected_version must be a positive integer")
305		}
306		switch input.Type {
307		case ActionNote, ActionLinkEvent, ActionResolve, ActionReopen,
308			ActionAddParticipant, ActionRemoveParticipant, ActionAssignOwner:
309		default:
310			return Request{}, validationErr("unknown action %q", input.Type)
311		}
312		if input.Content, err = trimRequired(actionContentField(input.Type), input.Content); err != nil {
313			return Request{}, err
314		}
315		return input, nil
316	}
317	
318	// actionContentField names the request member that carries each action's
319	// payload, used in validation messages.
320	func actionContentField(action string) string {
321		switch action {
322		case ActionLinkEvent:
323			return "event_id"
324		case ActionResolve, ActionReopen:
325			return "reason"
326		case ActionAddParticipant, ActionRemoveParticipant, ActionAssignOwner:
327			return "participant"
328		default:
329			return "content"
330		}
331	}
332	
333	func trimRequired(field, value string) (string, error) {
334		value = strings.TrimSpace(value)
335		if value == "" {
336			return "", validationErr("%s must not be empty", field)
337		}
338		return value, nil
339	}
340	
341	// Create accepts a new incident or replays an identical creation. A stored id
342	// presented with different normalized content conflicts.
343	func (r *Registry) Create(input Creation) (CreateResult, error) {
344		creation, err := NormalizeCreation(input)
345		if err != nil {
346			return CreateResult{}, err
347		}
348	
349		r.mu.Lock()
350		defer r.mu.Unlock()
351	
352		if existing, ok := r.incidents[creation.ID]; ok {
353			if existing.creation != creation {
354				return CreateResult{}, conflictErr(existing.version,
355					"incident %q already exists with different content", creation.ID)
356			}
357			// A creation replay returns the first result verbatim: open at
358			// version 1, even if the incident has moved on since.
359			return CreateResult{ID: creation.ID, Status: StatusOpen, Version: 1}, nil
360		}
361	
362		at := r.now()
363		record := NewCreationRecord(creation, at)
364		if r.beforeCommit != nil {
365			if err := r.beforeCommit(record); err != nil {
366				return CreateResult{}, err
367			}
368		}
369		r.incidents[creation.ID] = newIncidentState(creation, at)
370		return CreateResult{ID: creation.ID, Status: StatusOpen, Version: 1}, nil
371	}
372	
373	// Apply accepts one action or replays an identical one. Validation and every
374	// state check happen under the registry lock before persistence, so a
375	// rejected request leaves the incident untouched.
376	func (r *Registry) Apply(input Request) (ActionResult, error) {
377		req, err := NormalizeRequest(input)
378		if err != nil {
379			return ActionResult{}, err
380		}
381	
382		r.mu.Lock()
383		defer r.mu.Unlock()
384	
385		state, ok := r.incidents[req.IncidentID]
386		if !ok {
387			return ActionResult{}, notFoundErr("incident %q not found", req.IncidentID)
388		}
389	
390		// Idempotent replay is checked first: a retry of the first successful
391		// request still returns that result even though its expected_version is
392		// stale by now.
393		if prior, repeated := state.actions[req.ActionID]; repeated {
394			if prior.request != req {
395				return ActionResult{}, conflictErr(state.version,
396					"action %q already exists with different content", req.ActionID)
397			}
398			return ActionResult{IncidentID: state.id, ActionID: req.ActionID, Version: prior.resultVersion}, nil
399		}
400	
401		if err := r.checkAction(state, req); err != nil {
402			return ActionResult{}, err
403		}
404	
405		at := r.now()
406		record := NewActionRecord(req, at)
407		// A note's save capacity is measured on the bytes that would actually be
408		// saved in the save format — the complete normalized action record with
409		// its server timestamp, JSON escaping included, excluding the 8-byte
410		// storage frame header — not on the note length, request length, or the
411		// unescaped text. The check follows validation and every state check and
412		// precedes persistence, so an oversize note is refused without touching
413		// durable storage or advancing the incident.
414		if req.Type == ActionNote {
415			payload, err := MarshalRecord(record)
416			if err != nil {
417				return ActionResult{}, err
418			}
419			if len(payload) > MaxActionPayloadBytes {
420				return ActionResult{}, &OversizeActionError{Size: len(payload), Limit: MaxActionPayloadBytes}
421			}
422		}
423		if r.beforeCommit != nil {
424			if err := r.beforeCommit(record); err != nil {
425				return ActionResult{}, err
426			}
427		}
428		version := state.commit(req, at)
429		return ActionResult{IncidentID: state.id, ActionID: req.ActionID, Version: version}, nil
430	}
431	
432	// checkAction enforces optimistic versioning, the open/resolved state
433	// machine, and the link rules. It runs with the registry lock held.
434	func (r *Registry) checkAction(state *incidentState, req Request) error {
435		if req.ExpectedVersion != state.version {
436			return conflictErr(state.version,
437				"expected version %d but incident %q is at version %d",
438				req.ExpectedVersion, state.id, state.version)
439		}
440		switch req.Type {
441		case ActionNote:
442			if state.status != StatusOpen {
443				return conflictErr(state.version, "cannot add a note to a %s incident", state.status)
444			}
445		case ActionLinkEvent:
446			if err := r.linkConflictError(state, req); err != nil {
447				return err
448			}
449		case ActionResolve:
450			if state.status != StatusOpen {
451				return conflictErr(state.version, "incident %q is already resolved", state.id)
452			}
453		case ActionReopen:
454			if state.status != StatusResolved {
455				return conflictErr(state.version, "incident %q is not resolved", state.id)
456			}
457		case ActionAddParticipant, ActionRemoveParticipant, ActionAssignOwner:
458			if err := personnelConflictError(state, req); err != nil {
459				return err
460			}
461		}
462		return nil
463	}
464	
465	// linkViolation identifies one broken link_event eligibility rule without
466	// binding it to an error vocabulary: the live request path turns it into a
467	// 404/409 in its own wording, while startup replay turns it into a log
468	// inconsistency. Keeping the judgment independent of the wording means both
469	// entry paths enforce the very same business constraints.
470	type linkViolation int
471	
472	const (
473		linkOK linkViolation = iota
474		// linkClosed: a link was attempted while the incident was not open.
475		linkClosed
476		// linkMissing: the event id does not resolve in the event log (or there
477		// is no event lookup at all).
478		linkMissing
479		// linkWrongService: the event belongs to a different service.
480		linkWrongService
481		// linkAlreadyLinked: the incident already links this event.
482		linkAlreadyLinked
483	)
484	
485	// checkLinkEligibility evaluates the link rules shared by the live request
486	// path and startup replay: an event may be linked only while the incident is
487	// open, only when it exists and belongs to the incident's service, and only
488	// once per incident. It needs the registry solely to resolve events; every
489	// other input comes from the in-progress state and the normalized request.
490	// The returned service is the resolved event's service when the event was
491	// found, so the callers never have to look it up a second time.
492	func (r *Registry) checkLinkEligibility(state *incidentState, req Request) (linkViolation, string) {
493		if state.status != StatusOpen {
494			return linkClosed, ""
495		}
496		if r.events == nil {
497			return linkMissing, ""
498		}
499		service, found := r.events.LookupEvent(req.Content)
500		if !found {
501			return linkMissing, ""
502		}
503		if service != state.service {
504			return linkWrongService, service
505		}
506		if _, linked := state.linkSet[req.Content]; linked {
507			return linkAlreadyLinked, service
508		}
509		return linkOK, service
510	}
511	
512	// linkConflictError renders a shared link violation in the live request
513	// path's vocabulary: a missing event is a 404, every other violation is a
514	// 409-style conflict carrying the current version.
515	func (r *Registry) linkConflictError(state *incidentState, req Request) error {
516		switch violation, service := r.checkLinkEligibility(state, req); violation {
517		case linkOK:
518			return nil
519		case linkClosed:
520			return conflictErr(state.version, "cannot link an event to a %s incident", state.status)
521		case linkMissing:
522			return notFoundErr("event %q not found", req.Content)
523		case linkWrongService:
524			return conflictErr(state.version,
525				"event %q belongs to service %q, not %q", req.Content, service, state.service)
526		case linkAlreadyLinked:
527			return conflictErr(state.version,
528				"event %q is already linked to incident %q", req.Content, state.id)
529		}
530		return nil
531	}
532	
533	// personnelViolation identifies one broken personnel rule without binding
534	// it to an error vocabulary: the live request path turns it into a conflict
535	// carrying the current version, while startup replay turns it into a log
536	// inconsistency. Keeping the judgment independent of the wording means both
537	// entry paths enforce the very same business constraints.
538	type personnelViolation int
539	
540	const (
541		personnelOK personnelViolation = iota
542		// personnelClosed: a personnel action was attempted while not open.
543		personnelClosed
544		// personnelAlreadyMember: the add target already participates.
545		personnelAlreadyMember
546		// personnelNotMember: the remove target does not participate.
547		personnelNotMember
548		// personnelRemoveOwner: the remove target is the current owner.
549		personnelRemoveOwner
550		// personnelOwnerNonMember: the handover target does not participate.
551		personnelOwnerNonMember
552		// personnelOwnerUnchanged: the handover target is already the owner.
553		personnelOwnerUnchanged
554	)
555	
556	// checkPersonnelAction evaluates the personnel rules shared by the live
557	// request path and startup replay: personnel actions are accepted only
558	// while the incident is open; an added person must not already participate;
559	// a removed person must participate without being the current owner; an
560	// owner handover must target a different, already participating person.
561	func checkPersonnelAction(state *incidentState, req Request) personnelViolation {
562		if state.status != StatusOpen {
563			return personnelClosed
564		}
565		switch req.Type {
566		case ActionAddParticipant:
567			if _, member := state.participantSet[req.Content]; member {
568				return personnelAlreadyMember
569			}
570		case ActionRemoveParticipant:
571			if _, member := state.participantSet[req.Content]; !member {
572				return personnelNotMember
573			}
574			if req.Content == state.owner {
575				return personnelRemoveOwner
576			}
577		case ActionAssignOwner:
578			if _, member := state.participantSet[req.Content]; !member {
579				return personnelOwnerNonMember
580			}
581			if req.Content == state.owner {
582				return personnelOwnerUnchanged
583			}
584		}
585		return personnelOK
586	}
587	
588	// personnelConflictError renders a shared personnel violation in the live
589	// request path's vocabulary: a 409-style conflict carrying the current
590	// version.
591	func personnelConflictError(state *incidentState, req Request) error {
592		switch checkPersonnelAction(state, req) {
593		case personnelOK:
594			return nil
595		case personnelClosed:
596			return conflictErr(state.version, "cannot %s on a %s incident", participantRuleName(req.Type), state.status)
597		case personnelAlreadyMember:
598			return conflictErr(state.version, "%q is already a participant of incident %q", req.Content, state.id)
599		case personnelNotMember:
600			return conflictErr(state.version, "%q is not a participant of incident %q", req.Content, state.id)
601		case personnelRemoveOwner:
602			return conflictErr(state.version, "cannot remove the current owner %q from incident %q", req.Content, state.id)
603		case personnelOwnerNonMember:
604			return conflictErr(state.version, "cannot hand incident %q to non-participant %q", state.id, req.Content)
605		case personnelOwnerUnchanged:
606			return conflictErr(state.version, "%q is already the owner of incident %q", req.Content, state.id)
607		}
608		return nil
609	}
610	
611	// participantRuleName renders the personnel action names in error messages.
612	func participantRuleName(action string) string {
613		switch action {
614		case ActionAddParticipant:
615			return "add a participant"
616		case ActionRemoveParticipant:
617			return "remove a participant"
618		case ActionAssignOwner:
619			return "hand over ownership"
620		default:
621			return action
622		}
623	}
624	
625	// Get returns a point-in-time copy of one incident. The copy's people,
626	// status, links, version, and history all belong to the same committed
627	// version.
628	func (r *Registry) Get(id string) (Incident, error) {
629		r.mu.Lock()
630		defer r.mu.Unlock()
631		state, ok := r.incidents[id]
632		if !ok {
633			return Incident{}, notFoundErr("incident %q not found", id)
634		}
635		return state.snapshot(), nil
636	}
637	
638	func newIncidentState(creation Creation, at time.Time) *incidentState {
639		return &incidentState{
640			id:             creation.ID,
641			title:          creation.Title,
642			service:        creation.Service,
643			status:         StatusOpen,
644			version:        1,
645			participants:   []string{creation.Operator},
646			participantSet: map[string]struct{}{creation.Operator: {}},
647			owner:          creation.Operator,
648			links:          []string{},
649			linkSet:        make(map[string]struct{}),
650			actions:        make(map[string]committedAction),
651			history:        []Entry{{Operator: creation.Operator, Action: ActionCreate, Content: creation.Title, Version: 1, At: at}},
652			creation:       creation,
653		}
654	}
655	
656	// commit advances the state by one already-validated action and returns the
657	// new version.
658	func (s *incidentState) commit(req Request, at time.Time) int {
659		switch req.Type {
660		case ActionLinkEvent:
661			s.linkSet[req.Content] = struct{}{}
662			s.links = append(s.links, req.Content)
663		case ActionResolve:
664			s.status = StatusResolved
665		case ActionReopen:
666			s.status = StatusOpen
667		case ActionAddParticipant:
668			s.participantSet[req.Content] = struct{}{}
669			s.participants = append(s.participants, req.Content)
670		case ActionRemoveParticipant:
671			delete(s.participantSet, req.Content)
672			s.participants = removeString(s.participants, req.Content)
673		case ActionAssignOwner:
674			s.owner = req.Content
675		}
676		s.version++
677		s.history = append(s.history, Entry{
678			ActionID: req.ActionID,
679			Operator: req.Operator,
680			Action:   req.Type,
681			Content:  req.Content,
682			Version:  s.version,
683			At:       at,
684		})
685		s.actions[req.ActionID] = committedAction{request: req, resultVersion: s.version}
686		return s.version
687	}
688	
689	// removeString drops the first occurrence of value, preserving order.
690	func removeString(values []string, value string) []string {
691		for i, v := range values {
692			if v == value {
693				return append(values[:i], values[i+1:]...)
694			}
695		}
696		return values
697	}
698	
699	func (s *incidentState) snapshot() Incident {
700		links := slices.Clone(s.links)
701		history := make([]Entry, len(s.history))
702		copy(history, s.history)
703		participants := append([]string{}, s.participants...)
704		slices.Sort(participants)
705		return Incident{
706			ID:           s.id,
707			Title:        s.title,
708			Service:      s.service,
709			Status:       s.status,
710			Version:      s.version,
711			Participants: participants,
712			Owner:        s.owner,
713			Links:        links,
714			History:      history,
715		}
716	}
717

