	// shows link -> unlink -> relink.
	relink := `{"action_id":"l3","operator":"bob","expected_version":4,"action":"link_event","event_id":"e1"}`
	if s, res := postIncidentAction(t, p2, "INC-1", relink); s != http.StatusOK || incNumber(res["version"]) != 5 {
